input.command:
gh api graphql -f query='
{
  repository(owner: "chief-builder-lab", name: "clivsmcp-tier1-issue-triage-cb227815") {
    issues(states: OPEN, first: 20) {
      nodes {
        number
        title
        body
        labels(first: 10) {
          nodes {
            name
          }
        }
      }
    }
  }
}' --jq '.data.repository.issues.nodes[]'

curl -s -H "Authorization: token <GH_OAUTH_REDACTED>" -H "Accept: application/vnd.github.v3+json" "https://api.github.com/repos/chief-builder-lab/clivsmcp-tier1-issue-triage-cb227815/issues?state=open&per_page=50" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if isinstance(data, list):
    for i in data:
        print(json.dumps({'number':i['number'],'title':i['title'],'body':i.get('body',''),'labels':[l['name'] for l in i['labels']]}))
else:
    print(data)
"

